#include "edgeai/HybridBackend.hpp"
#include "edgeai/TransformerBackend.hpp"
#include "edgeai/EdgeModel.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2){std::cerr<<"usage: edgeai_inspect model.edge\n";return 2;}
 if(edgeai::is_transformer_file(argv[1])){edgeai::TransformerBackend b(argv[1]);const auto&m=b.model();std::cout<<"format=EDGEAI"<<(m.config.blocks>1?8:m.tokenizer.has_eos()?7:m.tokenizer.has_bos()?6:5)<<"\nvocab_size="<<m.tokenizer.vocab_size()<<"\nparameters="<<m.parameter_count()<<"\nresident_numeric_weights_bytes="<<m.weight_bytes()<<"\nsequence_state_payload_bytes="<<m.state_payload_bytes()<<"\nnumeric_working_bytes="<<b.numeric_working_bytes()<<"\nwindow="<<m.config.window<<"\noutput_precision="<<edgeai::precision_name(m.output.kind())<<"\n";}
 else if(edgeai::is_hybrid_file(argv[1])){edgeai::HybridBackend b(argv[1]);const auto& m=b.model();auto c=m.config;std::cout<<"format=EDGEAI"<<m.source_format_version<<"\nparameters="<<m.parameter_count()<<"\nresident_numeric_weights_bytes="<<m.weight_bytes()<<"\nsequence_state_payload_bytes="<<m.state_payload_bytes()<<"\nnumeric_working_bytes="<<b.numeric_working_bytes()<<"\nwindow="<<c.window<<"\ntrained_loops="<<c.loops<<"\navx2_kernel_available="<<edgeai::avx2_available()<<"\n";std::cout<<"query_precision="<<edgeai::precision_name(m.query.kind())<<"\nkey_precision="<<edgeai::precision_name(m.key.kind())<<"\nvalue_precision="<<edgeai::precision_name(m.value.kind())<<"\nproject_precision="<<edgeai::precision_name(m.project.kind())<<"\nup_precision="<<edgeai::precision_name(m.up.kind())<<"\ndown_precision="<<edgeai::precision_name(m.down.kind())<<"\noutput_precision="<<edgeai::precision_name(m.output.kind())<<"\n";}
 else{auto m=edgeai::EdgeModel::load(argv[1]);std::cout<<"format=EDGEAI2\nlegacy_parameter_count="<<m.parameter_count()<<"\nresident_numeric_weights_bytes="<<m.resident_weight_bytes()<<"\n";}return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
